def minPath(grid, k):
    n = len(grid)
    if k == 1:
        min_val = min(min(row) for row in grid)
        return [min_val]

    # Precompute positions of each value
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # For each cell, find the smallest neighbor value
    best_next = {}
    for i in range(n):
        for j in range(n):
            neighbors = []
            for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < n:
                    neighbors.append(grid[ni][nj])
            best_next[(i,j)] = min(neighbors) if neighbors else None

    # Start from the smallest value cell
    start_val = min(min(row) for row in grid)
    start_pos = pos[start_val]

    # Greedy: at each step, move to the neighbor with smallest value
    path = [start_val]
    cur_pos = start_pos
    for _ in range(k-1):
        next_val = best_next[cur_pos]
        next_pos = pos[next_val]
        path.append(next_val)
        cur_pos = next_pos

    return path
